+}
+
+.btn-page:hover:not(:disabled):not(.active) {
+    background: #f0f0f0;
+}
+
+.btn-page.active {
+    background: #0066cc;
+    color: white;
+    border-color: #0066cc;
+}
+
+.btn-page:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+

